def merge_intervals(intervals):
    if not intervals:
        return []

    # Create a sorted version of the input to avoid mutating the original list
    # Sorting by the start point ensures we can merge in a single pass
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = []
    for interval in sorted_intervals:
        # If merged is empty or the current interval starts after the last one ends
        if not merged or interval[0] > merged[-1][1]:
            # Append a new list object to ensure no reference to input objects
            merged.append([interval[0], interval[1]])
        else:
            # The intervals overlap or touch; merge them by updating the end point
            merged[-1][1] = max(merged[-1][1], interval[1])

    return merged

import heapq

def toposort(nodes, edges):
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Deduplicate edges to ensure duplicate input edges do not affect in-degree counts
    for u, v in set(edges):
        adj[u].append(v)
        in_degree[v] += 1

    # Use a min-heap to always select the lexicographically smallest available node
    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in the graph")

    return result

def stable_batches(items, limit):
    if not items:
        return []
    if limit <= 0:
        raise ValueError("Limit must be a positive integer.")

    batches = []
    current_batch = []
    current_sum = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Weight must be positive and not exceed the limit.")

        if current_sum + weight <= limit:
            current_batch.append(name)
            current_sum += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_sum = weight

    if current_batch:
        batches.append(current_batch)

    return batches

def parse_sse(chunks):
    buffer = bytearray()
    results = []
    current_data = []

    for chunk in chunks:
        buffer.extend(chunk)
        while b'\n' in buffer:
            pos = buffer.find(b'\n')
            line_bytes = buffer[:pos]
            del buffer[:pos + 1]

            if line_bytes.endswith(b'\r'):
                line_bytes = line_bytes[:-1]

            try:
                line = line_bytes.decode('utf-8')
            except UnicodeDecodeError:
                continue

            if not line:
                if current_data:
                    event_str = "\n".join(current_data)
                    if event_str == "[DONE]":
                        return results
                    results.append(event_str)
                    current_data = []
            elif line.startswith("data:"):
                content = line[5:]
                if content.startswith(" "):
                    content = content[1:]
                current_data.append(content)

    return results

import math

def retry_delay(attempt, base, cap):
    """
    Returns min(cap, base * 2**attempt).
    Handles large attempts without constructing massive integers.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be non-negative")

    if base == 0 or cap == 0:
        return 0.0

    # To prevent calculating 2**attempt which would create a massive integer if 
    # attempt is large (e.g., 10**9), we compare via logarithms.
    # base * 2**attempt >= cap  <=>  log2(base) + attempt >= log2(cap)
    # <=>  attempt >= log2(cap) - log2(base)
    # Using log2(cap) - log2(base) instead of log2(cap/base) avoids division overflow.
    try:
        threshold = math.log2(cap) - math.log2(base)
        if attempt >= threshold:
            return float(cap)
        else:
            # The else block is only entered if attempt < threshold.
            # Since threshold is at most ~2100 for finite floats, 
            # 2**attempt will not be a "huge integer" and float conversion is safe.
            return float(base * (2**attempt))
    except (OverflowError, ValueError):
        # Fallback for extreme floating point edge cases
        return float(cap)
